package io.github.miklires.mevents.event;
import io.github.miklires.mevents.api.EventState;import java.util.EnumSet;import java.util.Map;
public final class EventStateMachine {private static final Map<EventState,EnumSet<EventState>> ALLOWED=Map.of(EventState.SCHEDULED,EnumSet.of(EventState.PREPARING,EventState.CANCELLED),EventState.PREPARING,EnumSet.of(EventState.ACTIVE,EventState.CANCELLED),EventState.ACTIVE,EnumSet.of(EventState.COMPLETED,EventState.CANCELLED),EventState.COMPLETED,EnumSet.noneOf(EventState.class),EventState.CANCELLED,EnumSet.noneOf(EventState.class));public boolean canMove(EventState from,EventState to){return ALLOWED.get(from).contains(to);}public void require(EventState from,EventState to){if(!canMove(from,to))throw new IllegalStateException("Invalid event transition: "+from+" -> "+to);}}
